// Clean-room TSVC s116 profile; see package rights note.
fn put64(out:[*]u8,p:usize,v:i64)void{const b=@as(u64,@bitCast(v));for(0..8)|j|out[p+j]=@truncate(b>>(8*j));}
pub export fn tsvc_s116_unrolled_product_chain(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<8 or length>23)return -1;const v=input.?[0..length];const nr=v[0];const passes=v[1];if(nr<6 or nr>21 or @mod(nr-1,5)!=0 or passes<1 or passes>4)return -1;const n:usize=@intCast(nr);if(length!=2+n)return -1;var a=[_]i64{0}**21;for(0..n)|k|{if(v[2+k]!=-1 and v[2+k]!=1)return -1;a[k]=v[2+k];}if(output==null or capacity<8*n)return -2;for(0..@as(usize,@intCast(passes))) |_|{var i:usize=0;while(i<n-5):(i+=5){a[i]=a[i+1]*a[i];a[i+1]=a[i+2]*a[i+1];a[i+2]=a[i+3]*a[i+2];a[i+3]=a[i+4]*a[i+3];a[i+4]=a[i+5]*a[i+4];}}for(0..n)|k|put64(output.?,8*k,a[k]);return @intCast(n);}
